def solve(data):
    cache = {}
    order = []
    capacity = data[0]
    results = []

    for op in data[1:]:
        if op[0] == "put":
            key, value = op[1], op[2]
            if len(cache) >= capacity:
                if capacity > 0:
                    lru_key = order.pop()
                    del cache[lru_key]
            cache[key] = value
            order.append(key)
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                order.remove(key)
                order.append(key)
                results.append(cache[key])
            else:
                results.append(-1)

    return results

def solve(data):
    stack = []
    for token in data.split():
        if token in '+-*/':
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]

